import {createHash} from 'node:crypto';
export const bundleScopes=['profile','learning','pilot','exams','privacy','attendance','consultations','placement','course'];
const pick=(o,keys)=>Object.fromEntries(keys.filter(k=>o?.[k]!==undefined).map(k=>[k,o[k]]));
export function buildRightsBundle({db,state:s,subject:u,scopes}){
 const all=table=>db.prepare(`SELECT body FROM ${table} WHERE tenant_id=?`).all(u.tenantId).map(r=>JSON.parse(r.body));
 let scannedBytes=0;const own=table=>{const rows=[];for(const row of db.prepare(`SELECT body FROM ${table} WHERE tenant_id=? AND json_extract(body,'$.studentId')=?`).iterate(u.tenantId,u.id)){scannedBytes+=Buffer.byteLength(row.body);if(scannedBytes>16*1024*1024)throw Object.assign(Error('열람 범위를 나누어 검토해 주세요.'),{status:413});rows.push(JSON.parse(row.body));}return rows;};
 const out={schema:1,subjectId:u.id,scope:scopes,notice:'본인 개인정보의 검토용 사본입니다. 시험 문항·정답표와 다른 사람의 계정·인증정보는 포함하지 않습니다.'};
 if(scopes.includes('profile'))out.profile=pick(u,['id','name','username','role','className','active','studentStatus','validUntil','consentStatus']);
 if(scopes.includes('learning'))out.learning=own('learning_runs').map(r=>({...pick(r,['id','assignmentId','status','startedAt','updatedAt','submittedAt','writing','note']),run:pick(r.run,['phase','modelStep','index','reached','responses','annotations','archives']),reviews:Object.fromEntries(Object.entries(r.reviews||{}).map(([id,v])=>[id,pick(v,['outcome','note','at'])]))}));
 if(scopes.includes('pilot'))out.pilot=own('pilot_runs').map(r=>pick(r,['id','sessionId','studentId','grade','name','status','revision','answers','presented','times','exposure','observations','createdAt','startedAt','submittedAt']));
 if(scopes.includes('exams'))out.exams=s.attempts.filter(a=>a.tenantId===u.tenantId&&a.studentId===u.id).map(a=>pick(a,['id','assignmentId','status','startedAt','deadlineAt','submittedAt','answers','firstAnswers','flags','note','publishedNote','parentPublishedAt']));
 if(scopes.includes('privacy'))out.privacy={consents:s.privacy.consents.filter(c=>c.tenantId===u.tenantId&&(c.studentId===u.id||c.parentId===u.id)).map(c=>pick(c,['id','studentId','policyId','policyHash','action','required','optional','at'])),verifications:s.privacy.verifications.filter(v=>v.tenantId===u.tenantId&&(v.studentId===u.id||v.parentId===u.id)).map(v=>pick(v,['id','studentId','at','validUntil','revokedAt','method']))};
 if(scopes.includes('attendance'))out.attendance=s.attendance.filter(r=>r.tenantId===u.tenantId&&r.studentId===u.id).map(r=>pick(r,['id','date','status','note','createdAt','updatedAt']));
 if(scopes.includes('consultations'))out.consultations=s.consultations.filter(r=>r.tenantId===u.tenantId&&r.studentId===u.id).map(r=>pick(r,['id','note','createdAt','updatedAt']));
 if(scopes.includes('placement'))out.placement=own('learning_placements').map(r=>pick(r,['id','studentId','grade','version','status','branch','answers','initialAnswers','recommendation','decision','oralObservations','revision','createdAt','updatedAt','submittedAt','assignmentId']));
 if(scopes.includes('course'))out.course=own('learning_courses').map(r=>({studentId:r.studentId,...pick(r,['grade','createdAt','updatedAt']),plans:[r.plan,...r.history||[]].filter(Boolean).map(p=>({...pick(p,['id','course','name','activatedAt','completedAt','training','remediations']),checks:p.checks.map(c=>({...pick(c,['id','purpose','status','startedAt','submittedAt','answer','firstAnswer']),review:pick(c.review,['outcome','note','at'])}))}))}));
 const internal=new Set(['password','mfa','pendingMfa','deviceDraftKey','recoveryCodes','secret','token','key','checkBank','createdBy','teacherId','reviewedBy','by','actorId']);
 const clean=v=>Array.isArray(v)?v.map(clean):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).filter(([k])=>!internal.has(k)).map(([k,x])=>[k,clean(x)])):v;
 return clean(out);
}
export const bundleHash=value=>createHash('sha256').update(JSON.stringify(value)).digest('hex');
export function redactBundle(bundle,paths){
 const result=structuredClone(bundle);if(!Array.isArray(paths)||paths.length>200||new Set(paths).size!==paths.length)throw Object.assign(Error('제외할 문자열 위치를 확인해 주세요.'),{status:400});
 for(const path of paths){if(typeof path!=='string'||!path.startsWith('/')||path.length>300)throw Object.assign(Error('제외 위치가 올바르지 않습니다.'),{status:400});const keys=path.slice(1).split('/').map(k=>k.replaceAll('~1','/').replaceAll('~0','~'));if(keys.some(k=>['__proto__','constructor','prototype'].includes(k))||!bundleScopes.includes(keys[0]))throw Object.assign(Error('제외 위치를 확인해 주세요.'),{status:400});let target=result;for(const k of keys.slice(0,-1)){if(!target||typeof target!=='object'||!Object.hasOwn(target,k))throw Object.assign(Error('제외할 필드가 없습니다.'),{status:400});target=target[k];}const key=keys.at(-1);if(!Object.hasOwn(target||{},key)||typeof target[key]!=='string'||!['name','className','note','reason','writing','text','quote','transcript','reflection','evidence'].includes(key))throw Object.assign(Error('설명·메모 등 검토할 문자열만 제외할 수 있습니다.'),{status:400});target[key]='[별도 검토로 제외]';}
 return result;
}
export function redactionFields(value){const fields=[];const walk=(v,path)=>{if(!v||typeof v!=='object')return;for(const [k,x]of Object.entries(v)){const p=path+'/'+k.replaceAll('~','~0').replaceAll('/','~1');if(typeof x==='string'&&['name','className','note','reason','writing','text','quote','transcript','reflection','evidence'].includes(k)&&bundleScopes.includes(p.split('/')[1]))fields.push({path:p,text:x});else if(x&&typeof x==='object')walk(x,p);}};walk(value,'');return fields;}
